-- 0001: durable learners, challenge sessions and diagnosis attempts.
--
-- Applied by scripts/db-migrate.mjs inside one transaction. Do not add BEGIN/COMMIT here, and never
-- edit this file once it has been applied anywhere: the runner records its checksum and refuses a
-- changed file. Change the schema with a new, higher-numbered migration.
--
-- Conventions
--   * Every time is BIGINT milliseconds since the Unix epoch, matching the store contracts exactly
--     (the expiry arithmetic lives in src/server/session/expiry.ts and stays the only copy).
--   * Ids are opaque TEXT generated by the application. Nothing here assumes a format, so a
--     malformed id is simply "not found" instead of a type error.
--   * The raw learner token is never stored, only its SHA-256 hash.
--
-- Account-independence (see docs/architecture/durable-learner-session-storage.md, section 9):
-- a learner is an anonymous identity. There is deliberately no account column, no email, no
-- uniqueness that implies "one learner per person", and nothing that names an authentication
-- provider. A future accounts table can reference learners.id without changing this schema.

CREATE TABLE learners (
  id                  TEXT    PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 128),
  token_hash          TEXT    NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  revision            INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  created_at          BIGINT  NOT NULL,
  updated_at          BIGINT  NOT NULL,
  last_touched_at     BIGINT  NOT NULL,
  idle_expires_at     BIGINT  NOT NULL,
  absolute_expires_at BIGINT  NOT NULL,
  CHECK (idle_expires_at <= absolute_expires_at)
);

-- Purging looks for learners whose earlier deadline plus the grace period has passed.
CREATE INDEX learners_purge_idx ON learners ((LEAST(idle_expires_at, absolute_expires_at)));

CREATE TABLE challenge_sessions (
  id                TEXT    PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 128),
  learner_id        TEXT    NOT NULL REFERENCES learners (id) ON DELETE CASCADE,
  challenge_id      TEXT    NOT NULL CHECK (length(challenge_id) BETWEEN 1 AND 128),
  challenge_version TEXT    NOT NULL CHECK (length(challenge_version) BETWEEN 1 AND 256),
  status            TEXT    NOT NULL CHECK (status IN ('active', 'completed')),
  revision          INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  attempt_count     INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  wrong_attempts    INTEGER NOT NULL DEFAULT 0 CHECK (wrong_attempts >= 0 AND wrong_attempts <= attempt_count),
  created_at        BIGINT  NOT NULL,
  updated_at        BIGINT  NOT NULL,
  completed_at      BIGINT,
  -- What the learner was shown when they completed the challenge, kept exactly as shown.
  result            JSONB,
  superseded_at     BIGINT,
  -- A session is completed exactly when it has a completion time and a stored result.
  CHECK ((status = 'completed') = (completed_at IS NOT NULL)),
  CHECK ((status = 'completed') = (result IS NOT NULL)),
  -- A completed result is permanent: it is never superseded by a restart.
  CHECK (NOT (status = 'completed' AND superseded_at IS NOT NULL))
);

-- At most one CURRENT (not superseded) session per learner and challenge. A restart keeps the
-- replaced session as history, so this must be partial rather than a plain UNIQUE.
CREATE UNIQUE INDEX challenge_sessions_current_uq
  ON challenge_sessions (learner_id, challenge_id)
  WHERE superseded_at IS NULL;

CREATE INDEX challenge_sessions_learner_idx ON challenge_sessions (learner_id);

CREATE TABLE diagnosis_attempts (
  id            TEXT    PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 128),
  session_id    TEXT    NOT NULL REFERENCES challenge_sessions (id) ON DELETE CASCADE,
  challenge_id  TEXT    NOT NULL,
  seq           INTEGER NOT NULL CHECK (seq >= 1),
  -- The idempotency key, unique within the session.
  submission_id TEXT    NOT NULL CHECK (length(submission_id) BETWEEN 1 AND 128),
  request_hash  TEXT    NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  root_cause_id TEXT    NOT NULL CHECK (length(root_cause_id) >= 1),
  explanation   TEXT    NOT NULL,
  evidence      JSONB   NOT NULL CHECK (jsonb_typeof(evidence) = 'array'),
  outcome       TEXT    NOT NULL CHECK (outcome IN ('correct', 'incorrect')),
  created_at    BIGINT  NOT NULL,
  UNIQUE (session_id, seq),
  UNIQUE (session_id, submission_id)
);

-- A session has at most one correct attempt: the one that completed it. This is the last line of
-- defence behind the row lock that serialises attempts on a session.
CREATE UNIQUE INDEX diagnosis_attempts_one_correct_uq
  ON diagnosis_attempts (session_id)
  WHERE outcome = 'correct';
